<script setup lang="ts">
import { computed } from 'vue'
import { useRouter } from 'vue-router'
import { useAppStore } from '@/stores/app'
import { Plus, ArrowUpRight, CalendarClock, CheckCircle2, ListTodo, FolderKanban, ArrowRight, Sparkles, Circle } from 'lucide-vue-next'
import { statusLabels, priorityLabels } from '@/types'
const store = useAppStore()
const router = useRouter()
const today = new Date().toLocaleDateString('vi-VN', { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' })
const upcoming = computed(() => [...store.tasks].filter(t => t.status !== 'done').sort((a,b) => a.dueDate.localeCompare(b.dueDate)).slice(0, 5))
const formatDate = (d: string) => new Date(`${d.slice(0, 10)}T00:00:00`).toLocaleDateString('vi-VN', { day: '2-digit', month: '2-digit' })
</script>
<template>
  <section class="dashboard-view"><div class="page-heading heading-with-action"><div><div class="eyebrow">{{ today }}</div><h1>Chào mừng trở lại, {{ store.user.fullName.split(' ').slice(-1)[0] }} <span class="wave">✳</span></h1><p>Đây là những gì đang diễn ra trong không gian làm việc của bạn.</p></div><button class="btn btn-primary" @click="store.showTaskModal = true"><Plus :size="17"/> Tạo công việc</button></div>
    <div class="welcome-banner"><div><div class="banner-eyebrow"><Sparkles :size="15"/> TẬP TRUNG MỖI NGÀY</div><h2>Hôm nay là một ngày<br/>để tạo nên khác biệt.</h2><p>Biến những đầu việc nhỏ thành những kết quả lớn cùng TaskFlow.</p><button @click="router.push('/tasks')">Xem công việc <ArrowRight :size="16"/></button></div><div class="banner-decoration"><div class="deco-ring"><CheckCircle2 :size="83" :stroke-width="1.2"/></div></div></div>
    <div class="dashboard-stats"><div class="card-panel overview-stat"><span class="overview-icon purple"><ListTodo :size="20" /></span><p>Tổng công việc</p><strong>{{ store.tasks.length }}</strong><small>Trong không gian làm việc</small></div><div class="card-panel overview-stat"><span class="overview-icon cyan"><CalendarClock :size="20" /></span><p>Đang xử lý</p><strong>{{ store.pendingCount }}</strong><small>Cần theo dõi tiến độ</small></div><div class="card-panel overview-stat"><span class="overview-icon green"><CheckCircle2 :size="20" /></span><p>Đã hoàn thành</p><strong>{{ store.completedCount }}</strong><small>{{ store.donePercentage }}% tổng công việc</small></div><div class="card-panel overview-stat"><span class="overview-icon yellow"><FolderKanban :size="20" /></span><p>Dự án</p><strong>{{ store.projects.length }}</strong><small>Đang theo dõi</small></div></div>
    <div class="dashboard-columns"><section class="card-panel content-panel"><div class="content-section-title"><div><h2>Công việc sắp tới</h2><p>Những đầu việc cần bạn quan tâm.</p></div><button class="subtle-link" @click="router.push('/tasks')">Xem tất cả <ArrowUpRight :size="16"/></button></div><div v-if="!upcoming.length" class="empty-state">Chưa có công việc cần làm.</div><div v-for="task in upcoming" :key="task.taskId" class="upcoming-row"><button class="task-round-check" title="Đánh dấu hoàn thành" @click="store.setTaskStatus(task.taskId, 'done')"><Circle :size="19" /></button><div class="upcoming-info"><strong>{{ task.title }}</strong><span>{{ store.projects.find(p => p.projectId === task.projectId)?.projectName || 'Dự án' }} · {{ statusLabels[task.status] }}</span></div><span class="due-date">{{ formatDate(task.dueDate) }}</span><span class="priority-dot" :class="task.priority" :title="priorityLabels[task.priority]"></span></div></section>
    <section class="card-panel content-panel"><div class="content-section-title"><div><h2>Tiến độ dự án</h2><p>Tình trạng các dự án đang thực hiện.</p></div></div><div v-for="p in store.projects" :key="p.projectId" class="progress-project"><div class="project-progress-name"><span class="project-dot" :style="{ background: p.color }"></span><strong>{{ p.projectName }}</strong><span>{{ store.tasks.filter(t => t.projectId === p.projectId && t.status === 'done').length }}/{{ store.tasks.filter(t => t.projectId === p.projectId).length }}</span></div><div class="progress-track"><div :style="{ width: `${store.tasks.filter(t => t.projectId === p.projectId).length ? Math.round(store.tasks.filter(t => t.projectId === p.projectId && t.status === 'done').length / store.tasks.filter(t => t.projectId === p.projectId).length * 100) : 0}%`, background: p.color }"></div></div></div><button class="outline-wide" @click="router.push('/tasks')">Quản lý dự án <ArrowRight :size="16"/></button></section></div>
  </section>
</template>
